65	const BLOCK_SIZE = 3;
66	const BLOCK_PREMIUM = 60;
67	
68	const isBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE;
70	
71	const basePremiumOfItem = (item: Item): number => BASE_PREMIUMS[item.type];
72	
73	const sumOfItemPremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);
75	
76	const groupByType = (items: Item[]): Item[][] =>
77	  Object.values(
78	    items.reduce<Record<string, Item[]>>((groups, item) => {
79	      groups[item.type] = [...(groups[item.type] ?? []), item];
80	      return groups;
81	    }, {}),
82	  );
83	
84	const basePremiumOfGroup = (items: Item[]): number =>
85	  isBlock(items) ? BLOCK_PREMIUM : sumOfItemPremiums(items);
86	
87	const policyBasePremium = (items: Item[]): number =>
88	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
89	
90	const CURSED_SURCHARGE_RATE = 0.5;
91	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
92	
93	const HIGH_ENCHANTMENT_THRESHOLD = 5;
94	
95	const isCursed = (item: Item): boolean => item.cursed === true;
96	
97	const isHighlyEnchanted = (item: Item): boolean =>
98	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
99	
100	const NO_SURCHARGE_RATE = 0;
101	
102	const surchargeRateOfItem = (item: Item): number =>
103	  (isCursed(item) ? CURSED_SURCHARGE_RATE : NO_SURCHARGE_RATE) +
104	  (isHighlyEnchanted(item)
105	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
106	    : NO_SURCHARGE_RATE);
107	
108	const surchargeOfItem = (item: Item): number =>
109	  basePremiumOfItem(item) * surchargeRateOfItem(item);
110	
111	const sumOfItemSurcharges = (items: Item[]): number =>
112	  items.reduce((sum, item) => sum + surchargeOfItem(item), 0);
113	
114	const quote = (items: Item[]): QuoteResult => ({
115	  premium:
116	    PROCESSING_FEE + policyBasePremium(items) + sumOfItemSurcharges(items),
117	});
118	
119	export const runScenario = (scenario: Scenario): ScenarioResult => {
120	  const firstStep = scenario.steps[0] as QuoteStep;
121	  return { results: [quote(firstStep.items)] };
122	};
